begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
delete from public.user_profiles;
insert into auth.users(id,email,email_confirmed_at) values('91000000-0000-0000-0000-000000000001','easy-operations@kapa.test',now());
insert into public.user_profiles(user_id,partner_id,display_name) select '91000000-0000-0000-0000-000000000001',id,'John' from public.partners where code='john';
update public.business_settings set energy_kwh_cost=0,labor_hour_cost=0;
create function pg_temp.op(action text,p jsonb) returns jsonb language sql as $$select public.business_operate(action,p,gen_random_uuid())$$;
create function pg_temp.purchase() returns uuid language sql as $$select id from public.purchases where lot_id='93000000-0000-0000-0000-000000000001'$$;
create function pg_temp.debt() returns uuid language sql as $$select id from public.debts where purchase_id=pg_temp.purchase()$$;
create temp table easy_fixture(k text primary key,v jsonb);
insert into easy_fixture values('piece','{"description":"Pieza personalizada","quantity":"1","printer_id":"92000000-0000-0000-0000-000000000001","hours":"1","materials":[{"lot_id":"93000000-0000-0000-0000-000000000001","piece_grams":"10"}],"multiplier":"3"}');
grant select on easy_fixture to authenticated;
select is(private.op_depreciation(10000,16810476172.91),1000::numeric,'Dieciséis mil millones se limitan a 10% del material');
select is(private.op_depreciation(.05,100),0::numeric,'Redondeo hacia abajo garantiza que nunca supera 10%');
select is(private.op_depreciation(1000,15),15::numeric,'Se conserva la amortización menor al límite');
select is(private.op_depreciation(0,100),0::numeric,'Sin costo material no hay amortización');
set local request.jwt.claim.sub='91000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((public.business_read('capabilities')->>'schema_version')::integer,3,'La interfaz exige la versión con cálculo corregido');
select lives_ok($$select pg_temp.op('lot_purchase','{"id":"93000000-0000-0000-0000-000000000001","brand":"Prueba corrección","kind":"PLA","color":"Rojo","initial_grams":1000,"total":90000,"paid":90000,"description":"Compra mal clasificada","method":"tarjeta","allow_negative_cash":true,"authorization_reason":"Registro original equivocado"}')$$,'Reproducir compra que quedó como caja negativa');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,(-90000)::numeric,'La compra errónea demuestra el caso reportado');
select lives_ok($$select pg_temp.op('purchase_reclassify',jsonb_build_object('purchase_id',pg_temp.purchase(),'version',1,'paid',0,'financing','credit_card','installments',3,'next_due',current_date,'installment_interest',100,'reason','Fue comprada con tarjeta de crédito'))$$,'Corregir a tarjeta sin borrar el movimiento original');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,0::numeric,'La compensación elimina la caja negativa equivocada');
select is((select count(*) from public.cash_entries),2::bigint,'Conserva cargo y corrección trazables');
select is((select count(*) from public.debts),1::bigint,'La financiación crea una sola deuda');
select is((select principal from public.debts),90000::numeric,'Tarjeta reconoce el total como deuda');
select is((select on_hand_grams from public.inventory_lots),1000::numeric,'Corregir pago no cambia stock físico');
select is((select purchase_cost from public.inventory_lots),90000::numeric,'Corregir pago no cambia costo material');
select is((public.business_read('cash')->'summary'->>'cumulative_profit')::numeric,0::numeric,'La compensación de caja no inventa utilidad');
select lives_ok($$select pg_temp.op('lot_update','{"lot_id":"93000000-0000-0000-0000-000000000001","version":1,"brand":"Prueba corrección","kind":"PLA","color":"Vinotinto","color_hex":"#701b34"}')$$,'Editar nombre y muestra visual del color');
select is(public.business_read('inventory')->'rows'->0->>'color','Vinotinto','El inventario muestra el color corregido');
select is(public.business_read('inventory')->'rows'->0->>'color_hex','#701b34','La vista recibe un tono visual validado');
select is((public.business_read('material_summary')->'rows'->0->>'grams')::numeric,1000::numeric,'Resumen agrupa el filamento físico por color');
select is((public.business_read('material_summary')->'stock_totals'->>'rolls')::integer,1,'Los totales se calculan sobre todo el inventario');
select throws_ok($$select pg_temp.op('lot_update','{"lot_id":"93000000-0000-0000-0000-000000000001","version":1,"brand":"Otro","kind":"PLA","color":"Azul"}')$$,'PT409',null,'No sobreescribe una edición concurrente de color');
select lives_ok($$select pg_temp.op('cash_create','{"category":"capital","description":"Aporte real para cuotas","amount":50000}');select pg_temp.op('debt_pay',jsonb_build_object('debt_id',pg_temp.debt(),'principal',30000,'interest',100))$$,'Registrar un abono real de tarjeta');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,19900::numeric,'Solo cuotas realmente pagadas descuentan caja');
select throws_ok($$select pg_temp.op('purchase_reclassify',jsonb_build_object('purchase_id',pg_temp.purchase(),'version',2,'paid',80000,'financing','credit_card','reason','No se pueden desaparecer pagos'))$$,'PT422',null,'Protege capital ya abonado al corregir pago inicial');
select lives_ok($$select pg_temp.op('purchase_reclassify',jsonb_build_object('purchase_id',pg_temp.purchase(),'version',2,'paid',0,'financing','credit_card','installments',2,'next_due',current_date+30,'installment_interest',50,'reason','Plan actualizado con el banco'))$$,'Editar deuda sin borrar cuotas abonadas');
select is((select count(*) from public.debt_payments),1::bigint,'El pago real permanece tras reprogramar');
select is((select count(*) from public.debt_installments where superseded_at is not null),3::bigint,'El plan anterior permanece identificado como reemplazado');
select is((select count(*) from public.debt_installments where superseded_at is null),2::bigint,'Solo las cuotas pendientes nuevas están activas');
select is(jsonb_array_length(public.business_read('debts')->'rows'->0->'installments'),2,'La edición no duplica cuotas en pantalla');
select is((public.business_read('cash')->'summary'->>'debt_balance')::numeric,60000::numeric,'La deuda resta los abonos del capital total');
select is((public.business_report('installments',current_date-1,current_date+1000)->>'total')::integer,2,'Los reportes excluyen cuotas reemplazadas');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,19900::numeric,'Editar el plan futuro no mueve caja');
select throws_ok($$select pg_temp.op('debt_pay',jsonb_build_object('debt_id',pg_temp.debt(),'installment_id',(select id from public.debt_installments where superseded_at is not null order by number limit 1),'principal',1,'interest',0))$$,'22023',null,'No permite pagar otra vez el plan reemplazado');
select lives_ok($$select pg_temp.op('printer_save','{"id":"92000000-0000-0000-0000-000000000001","name":"Impresora con valor equivocado","model":"A1","acquisition_cost":16810476172.91,"useful_hours":1,"power_kw":0}');select pg_temp.op('customer_save','{"id":"94000000-0000-0000-0000-000000000001","name":"Cliente sin anticipo"}')$$,'Preparar el caso de amortización extrema');
select is((public.preview_production_cost((select v from easy_fixture where k='piece'))->>'depreciation_cost')::numeric,90::numeric,'Un material de 900 COP admite máximo 90 COP de amortización');
select is((public.preview_production_cost((select v from easy_fixture where k='piece'))->>'price')::numeric,2970::numeric,'Sugiere precio sobre costos corregidos y no sobre miles de millones');
select lives_ok($$select pg_temp.op('order_quick_create',jsonb_build_object('id','95000000-0000-0000-0000-000000000001','customer_id','94000000-0000-0000-0000-000000000001','description','Nuevo pedido sin anticipo','promised_at','2030-01-01T12:00:00-05:00','lines',jsonb_build_array((select v from easy_fixture where k='piece'))))$$,'Crear pedido directo sin anticipo y sin ir al catálogo');
select is((select status from public.orders where id='95000000-0000-0000-0000-000000000001'),'confirmed','El pedido sin anticipo queda confirmado');
select is((public.business_read('balances')->>'total')::integer,1,'El apartado de saldos incluye al cliente que no adelantó');
select is(jsonb_array_length(public.business_read('dashboard')->'alerts'->'balances'),1,'Inicio notifica quién debe');
select lives_ok($$select pg_temp.op('order_quick_create',jsonb_build_object('id','95000000-0000-0000-0000-000000000002','customer_id','94000000-0000-0000-0000-000000000001','description','Trabajo ya impreso y entregado','promised_at','2030-01-02T12:00:00-05:00','initial_status','delivered','already_printed',true,'lines',jsonb_build_array((select v from easy_fixture where k='piece'))))$$,'Registrar trabajo que ya estaba impreso y entregado');
select is((select status from public.orders where id='95000000-0000-0000-0000-000000000002'),'delivered','Se registra directamente el estado real');
select is((select on_hand_grams from public.inventory_lots),990::numeric,'Registra consumo real del trabajo ya impreso una sola vez');
select is((select depreciation_cost from public.production_runs),90::numeric,'La producción real también respeta el límite del 10%');
select is((public.business_read('receivables')->>'total')::integer,1,'Entregado sin anticipo permanece como cuenta por cobrar');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,19900::numeric,'Registrar entrega no inventa pagos del cliente');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','95000000-0000-0000-0000-000000000001','version',(select version from public.orders where id='95000000-0000-0000-0000-000000000001'),'status','printing'))$$,'Cambiar directamente al estado real sin recorrer pasos artificiales');
select is((public.business_read('orders_printing')->>'total')::integer,1,'El filtro visual devuelve el estado elegido desde el servidor');
select is((public.business_read('orders')->'state_counts'->>'delivered')::integer,1,'El tablero cuenta todos los entregados aunque exista paginación');
select throws_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','95000000-0000-0000-0000-000000000002','version',(select version from public.orders where id='95000000-0000-0000-0000-000000000002'),'status','ready_delivery'))$$,'PT422',null,'Corregir una entrega existente requiere explicar el cambio');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','95000000-0000-0000-0000-000000000002','version',(select version from public.orders where id='95000000-0000-0000-0000-000000000002'),'status','ready_delivery','correction_reason','La entrega estaba registrada por error'))$$,'Corregir estado de una entrega registrada equivocadamente');
select is((select delivered_quantity from public.order_lines where order_id='95000000-0000-0000-0000-000000000002'),0,'La corrección conserva eventos y retira la marca de entrega');
select is((select on_hand_grams from public.inventory_lots),990::numeric,'Corregir estado no recupera plástico consumido');
select lives_ok($$select pg_temp.op('order_quick_create',jsonb_build_object('id','95000000-0000-0000-0000-000000000003','customer_id','94000000-0000-0000-0000-000000000001','description','Impreso todavía pendiente de anticipo','promised_at','2030-01-03T12:00:00-05:00','initial_status','pending_deposit','already_printed',true,'lines',jsonb_build_array((select v from easy_fixture where k='piece'))))$$,'Confirmar piezas ya impresas también registra consumo cuando se deja el anticipo pendiente');
select is((select status from public.orders where id='95000000-0000-0000-0000-000000000003'),'pending_deposit','Respeta el estado elegido aunque haya consumo registrado');
select is((select on_hand_grams from public.inventory_lots),980::numeric,'La confirmación explícita siempre registra las piezas faltantes');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','95000000-0000-0000-0000-000000000003','version',(select version from public.orders where id='95000000-0000-0000-0000-000000000003'),'status','printing','confirm_without_deposit',true,'confirm_record_completed',true))$$,'Cambiar al estado real con unidades ya producidas no las produce otra vez');
select is((select on_hand_grams from public.inventory_lots),980::numeric,'Reconfirmar no duplica el consumo registrado');
reset role;
set local request.jwt.claim.sub='91000000-0000-0000-0000-000000000099';
set local role authenticated;
select throws_ok($$select public.business_read('purchase_detail',p_id:='00000000-0000-0000-0000-000000000000')$$,'42501',null,'Una cuenta ajena no lee información de financiación');
select throws_ok($$select pg_temp.op('purchase_reclassify','{}')$$,'42501',null,'Una cuenta ajena no corrige caja o deuda');
reset role;
select * from finish();
rollback;
